      const relays = body && typeof body.relays === "object" && body.relays ? Object.keys(body.relays).slice(0, 16) : [];
      return {
        host,
        url: fetched.url,
        status: fetched.status,
        names,
        nameCount: Object.keys(rawNames).length,
        relays,
      };
